const express = require('express');
const session = require('express-session');
const RedisStore = require('connect-redis').default;
const Redis = require('ioredis');

const app = express();
const redisClient = new Redis(process.env.REDIS_URL);

const redisStore = new RedisStore({
  client: redisClient,
  prefix: 'sess:'
});

app.use(session({
  store: redisStore,
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false
}));

app.get('/api/admin/sessions/:sessionId/inspect', (req, res) => {
  if (!req.session || !req.session.user) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Strict role check: only platform super-admins can inspect sessions
  if (req.session.user.role !== 'SUPER_ADMIN') {
    return res.status(403).json({ error: 'Access denied: insufficient administrative permissions' });
  }

  redisStore.get(req.params.sessionId, (err, sessionData) => {
    if (err) {
      return res.status(500).json({ error: 'Store lookup failed' });
    }
    if (!sessionData) {
      return res.status(404).json({ error: 'Session not found' });
    }

    // Enforce tenant isolation even for admins: cannot inspect sessions from other organizations
    if (sessionData.tenantId !== req.session.user.tenantId) {
      return res.status(403).json({ error: 'Cannot inspect cross-tenant sessions' });
    }

    // Sanitize credentials before responding
    const sanitizedData = { ...sessionData };
    delete sanitizedData.oauthToken;
    delete sanitizedData.passwordHash;

    res.json({
      sessionId: req.params.sessionId,
      sessionData: sanitizedData
    });
  });
});

app.listen(3001);
